function ExternalSiteIcon({ name }: { name: string }) {
  if (name === 'Официальный сайт') {
    return (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" style={{ flexShrink: 0 }}>
        <circle cx="12" cy="12" r="10" stroke="#cbd5e1" strokeWidth="1.8" />
        <ellipse cx="12" cy="12" rx="4.5" ry="10" stroke="#cbd5e1" strokeWidth="1.4" />
        <line x1="2" y1="12" x2="22" y2="12" stroke="#cbd5e1" strokeWidth="1.4" />
        <text x="12" y="14" textAnchor="middle" fill="#cbd5e1" fontSize="5.5" fontWeight="900" fontFamily="sans-serif">WWW</text>
      </svg>
    )
  }
  if (name === 'Crunchyroll') {
    return <CrunchyrollIcon size={18} />
  }
  if (name === 'Anime-Planet') {
    return <AnimePlanetIcon width={22} height={11} />
  }
  if (name === 'Netflix') {
    return <NetflixIcon height={18} />
  }
  if (name === 'YouTube') {
    return <YoutubeIcon width={20} height={14} />
  }
  if (name === 'Bilibili') {
    return <BilibiliIcon width={22} height={10} />
  }
  if (name === 'Reddit') {
    return <RedditIcon width={24} height={8} />
  }
  if (name === 'MyAnimeList') {
    return (
      <div style={{ background: '#2e51a2', borderRadius: 4, padding: '2px 4px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
        <MalIcon width={20} height={9} color="#fff" />
      </div>
    )
  }
  if (name === 'World Art') {
    return (
      <div style={{ background: '#851414', borderRadius: 4, padding: '3px 4px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
        <WorldArtIcon width={18} height={10} color="#ffffff" />
      </div>
    )
  }
  if (name === 'КиноПоиск') {
    return (
      <div style={{ background: '#000000', borderRadius: 4, width: 20, height: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
        <KinopoiskIcon size={14} />
      </div>
    )
  }
  if (name === 'Shikimori') {
    return (
      <div style={{ background: '#ffffff', borderRadius: 4, width: 20, height: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
        <ShikimoriIcon size={14} color="#111827" />
      </div>
    )
  }

  // Если точной иконки нет — первая буква названия (для Википедии 'W', для остальных первая буква)
  let letter = name.trim().charAt(0).toUpperCase()
  if (name.includes('Википедия') || name.includes('Wikipedia') || name.includes('ウィキペディア')) {
    letter = 'W'
  }

  return (
    <div
      style={{
        width: 20,
        height: 20,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: 13,
        fontWeight: 600,
        color: '#cbd5e1',
        flexShrink: 0,
        fontFamily: 'inherit',
      }}
    >
      {letter}
    </div>
  )
}

